import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/%E7%9C%9F%E5%AE%9E%E9%9D%A2%E7%BB%8F/%E9%A3%9E%E9%80%9F%E5%88%9B%E6%96%B0/","title":"飞速创新 | notes","lang":"zh-CN","frontmatter":{"title":"飞速创新","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/真实面经/飞速创新/","description":"业务 工作流引擎 PM物料管理平台 介绍独立开发的需求-辅料到货计划 image-20250318195523190 表设计 需求计划表：月份，日期（到每一天），版本，辅料，数量 库存表：辅料，数量 采购订单：辅料、单位、订单未到货数量、采购订单发货时间、计划到货时间 仓库作业能力：最大作业能力（1托盘-x单位） 到货计划表：月份，日期（到每一天），版...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"飞速创新\\",\\"image\\":[\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250409215513161.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318202935210.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318205516306.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318205915994.png\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/%E7%9C%9F%E5%AE%9E%E9%9D%A2%E7%BB%8F/%E9%A3%9E%E9%80%9F%E5%88%9B%E6%96%B0/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"飞速创新"}],["meta",{"property":"og:description","content":"业务 工作流引擎 PM物料管理平台 介绍独立开发的需求-辅料到货计划 image-20250318195523190 表设计 需求计划表：月份，日期（到每一天），版本，辅料，数量 库存表：辅料，数量 采购订单：辅料、单位、订单未到货数量、采购订单发货时间、计划到货时间 仓库作业能力：最大作业能力（1托盘-x单位） 到货计划表：月份，日期（到每一天），版..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250409215513161.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":8.01,"words":2402},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/真实面经/飞速创新.md","headers":[],"bulletin":true}`),a={name:`飞速创新.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>业务 工作流引擎 PM物料管理平台</p><h2 id="介绍独立开发的需求-辅料到货计划" tabindex="-1"><a class="header-anchor" href="#介绍独立开发的需求-辅料到货计划"><span>介绍独立开发的需求-辅料到货计划</span></a></h2><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318195523190.png" alt="image-20250318195523190" style="zoom:200%;"><p><strong>表设计</strong></p><p>需求计划表：月份，日期（到每一天），版本，辅料，数量</p><p>库存表：辅料，数量</p><p>采购订单：辅料、单位、订单未到货数量、采购订单发货时间、计划到货时间</p><p>仓库作业能力：最大作业能力（1托盘-x单位）</p><p>到货计划表：月份，日期（到每一天），版本，辅料，数量</p><p><strong>整体逻辑</strong></p><ol><li>生产工单的成品需要的辅料（来源辅料BOM）生成辅料需求计划</li><li>根据需求，库存，仓库作业能力 测算 每天需要的到货量</li><li>根据采购订单去分配给对应的供应商</li></ol><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250409215513161.png" alt="image-20250409215513161" tabindex="0" loading="lazy"><figcaption>image-20250409215513161</figcaption></figure><h2 id="开发过程中-怎么实现一个用户角色权限管理系统的整体方案" tabindex="-1"><a class="header-anchor" href="#开发过程中-怎么实现一个用户角色权限管理系统的整体方案"><span>开发过程中，怎么实现一个用户角色权限管理系统的整体方案</span></a></h2><p>根据 用户-角色 设计到菜单、按钮的权限控制</p><p>用户表</p><p>角色表</p><p>角色用户关联表</p><p>菜单表</p><p>按钮表</p><p>角色菜单关联表</p><p>角色按钮关联表</p><p><strong>菜单展示逻辑</strong></p><p>用户登录后，前端发送请求到后端，获取用户所属角色的菜单权限。</p><p><strong>按钮显示逻辑</strong></p><p>当用户访问某个页面时，前端发送请求到后端，获取用户所属角色的按钮权限。</p><p>如果用户通过禁用JavaScript来绕过前端的权限校验，那么前端的任何基于JavaScript的校验逻辑都将失效。</p><p>后端进行权限校验</p><h2 id="项目上遇到的难解决的问题" tabindex="-1"><a class="header-anchor" href="#项目上遇到的难解决的问题"><span>项目上遇到的难解决的问题</span></a></h2><p>服务器无法处理请求，nginx代理其中一台服务器处理不了请求，直接访问也打不开页面</p><p>1.<strong>日志查看出现GC</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>jmap -dump 查看是否内存溢出</span></span>
<span class="line"><span>发现某个对象频繁创建！！！复制❌！已复制！</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>2.查看进程占用高达1400%</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-"><span class="line"><span>top -Hp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>printf %\\n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>jstack 线程 获取堆栈信息</span></span>
<span class="line"><span>发现某个方法一直在执行，分析可能是数据量大/数据库死锁复制❌！已复制！</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这个方法是统计报表用到，每个月底会执行，数据每天20w作业，统计实验室的温度，湿度；获取数据湖的数据</p><p>本地debug 直接卡死，GC</p><p>多线程并行分批处理，发现一天一天执行时间还是10分钟左右</p><p>排查sql问题，sql执行1-3s</p><p>方法里面打印执行时间，发现查询数据慢</p><p>可能是sql字段过多，映射实体较慢</p><p>修改xml指定具体字段，换指定jdbc类型和java类型转换</p><p>发现问题还是没有解决</p><p>可能是mybatis默认的反射（运行时动态解析）填充字段慢</p><p>修改为构造器（编译时，调用类的构造函数）方式映射</p><p>修改完执行时间减少到1-2分钟（每一天的数据）</p><h2 id="上一家公司如何承接项目-项目开发人员架构" tabindex="-1"><a class="header-anchor" href="#上一家公司如何承接项目-项目开发人员架构"><span>上一家公司如何承接项目，项目开发人员架构</span></a></h2><h2 id="list的集合实现-arraylist和linkedlist的区别" tabindex="-1"><a class="header-anchor" href="#list的集合实现-arraylist和linkedlist的区别"><span>List的集合实现-ArrayList和LinkedList的区别</span></a></h2><p>ArrayList基于数组</p><p>LinkedList基于双向链表</p><p>本质是数组和链表的区别</p><p>数组通过下标快速访问，在移动元素的情况下，插入和删除较慢</p><p>链表在中间插入和删除需要找到对应元素，才能删除</p><h2 id="有没有其它优化的链表结构能使从中间插入或删除时的时间复杂度更快" tabindex="-1"><a class="header-anchor" href="#有没有其它优化的链表结构能使从中间插入或删除时的时间复杂度更快"><span>有没有其它优化的链表结构能使从中间插入或删除时的时间复杂度更快</span></a></h2><p>跳表（Skip List）：跳表的查找和插入操作的平均时间复杂度可以达到 O(log n)</p><p><a href="https://www.mianshiya.com/question/1780933295597449217" target="_blank" rel="noopener noreferrer">Redis 中跳表的实现原理是什么？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p>多层链表实现，底层链表保存所有元素，每一层链表都是下一层的子集</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318202935210.png" alt="image-20250318202935210" tabindex="0" loading="lazy"><figcaption>image-20250318202935210</figcaption></figure><h2 id="hashmap插入流程" tabindex="-1"><a class="header-anchor" href="#hashmap插入流程"><span>HashMap插入流程</span></a></h2><p>HashMap主要由<strong>数组和链表</strong>组成，存储键值对，不是线程安全的。</p><p>插入数据用<code>put</code>，<code>get</code>查询数据以及扩容的方式。</p><p>jdk1.7和1.8的主要区别在于<strong>头插</strong>和<strong>尾插</strong>方式的修改,头插容易导致HashMap链表死循环，并且1.8后加入红黑树性能有提升。</p><p>https://blog.csdn.net/littlehaes/article/details/105241194</p><h3 id="put插入数据流程" tabindex="-1"><a class="header-anchor" href="#put插入数据流程"><span><a href="http://xiaofei.site:10082/#/%E9%9D%A2%E8%AF%95/%E9%9D%A2%E8%AF%95%E9%A2%98?id=put%E6%8F%92%E5%85%A5%E6%95%B0%E6%8D%AE%E6%B5%81%E7%A8%8B" target="_blank" rel="noopener noreferrer">put插入数据流程</a></span></a></h3><p>向map插入数据时获得<strong>key的hash与数组长度-1进行与运算</strong>【(n-1)&amp;hash】。找到数组中的位置后，如果数组中<strong>没有元素，则直接存入</strong>，有元素则<strong>判断key是否相同</strong>，<strong>相同则覆盖</strong>，<strong>不相同则插入到链表的尾部</strong>，<strong>如果链表长度超过8并且数据长度超过64，则会转换成红黑树</strong>（CRUD操作的时间复杂度都为O(log n)），最后判断数组长度是否超过<strong>默认长度（16）* 负载因子（0.75）</strong>，超过则进行扩容。</p><h3 id="get查询数据" tabindex="-1"><a class="header-anchor" href="#get查询数据"><span><a href="http://xiaofei.site:10082/#/%E9%9D%A2%E8%AF%95/%E9%9D%A2%E8%AF%95%E9%A2%98?id=get%E6%9F%A5%E8%AF%A2%E6%95%B0%E6%8D%AE" target="_blank" rel="noopener noreferrer">get查询数据</a></span></a></h3><p>首先计算hash值，去数组查询，是红黑树就去红黑树查，链表就遍历链表查询</p><h3 id="resize扩容过程" tabindex="-1"><a class="header-anchor" href="#resize扩容过程"><span><a href="http://xiaofei.site:10082/#/%E9%9D%A2%E8%AF%95/%E9%9D%A2%E8%AF%95%E9%A2%98?id=resize%E6%89%A9%E5%AE%B9%E8%BF%87%E7%A8%8B" target="_blank" rel="noopener noreferrer">resize扩容过程</a></span></a></h3><p>对key重新计算hash，把数据拷贝到新的数组</p><h2 id="hashmap默认16-负载因子0-75-每次到12-就扩容了-那剩下4个元素不是浪费了吗-为什么" tabindex="-1"><a class="header-anchor" href="#hashmap默认16-负载因子0-75-每次到12-就扩容了-那剩下4个元素不是浪费了吗-为什么"><span>HashMap默认16，负载因子0.75 ，每次到12，就扩容了，那剩下4个元素不是浪费了吗，为什么</span></a></h2><p><a href="https://www.mianshiya.com/question/1780933294758588418" target="_blank" rel="noopener noreferrer">为什么 Java 中 HashMap 的默认负载因子是 0.75？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p>负载因子过高，导致剩余利用空间不足，导致hash冲突过多，导致查找，插入，删除的效率降低</p><p>负载因子过低，导致空间利用不足</p><h2 id="hash冲突除了通过链表这种拉链法形式解决有了解过其它的方案吗" tabindex="-1"><a class="header-anchor" href="#hash冲突除了通过链表这种拉链法形式解决有了解过其它的方案吗"><span>hash冲突除了通过链表这种拉链法形式解决有了解过其它的方案吗</span></a></h2><p><a href="https://www.mianshiya.com/question/1821481519536611330" target="_blank" rel="noopener noreferrer">什么是 Hash 碰撞？怎么解决哈希碰撞？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>开放寻址</strong></p><p>寻找下一个空闲位置</p><p>线性探查（寻找下一个连续槽位）、平方探查（类似线性探查，步长为二次方，减少聚焦问题）、双散列（第一次决定初始位置，第二次决定探查步长）</p><p><strong>双重哈希</strong></p><p>使用多个hash函数重新计算</p><h2 id="数据库隔离级别分别解决了什么问题" tabindex="-1"><a class="header-anchor" href="#数据库隔离级别分别解决了什么问题"><span>数据库隔离级别分别解决了什么问题</span></a></h2><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318205516306.png" alt="image-20250318205516306" tabindex="0" loading="lazy"><figcaption>image-20250318205516306</figcaption></figure><p><a href="https://www.mianshiya.com/question/1780933295492591617" target="_blank" rel="noopener noreferrer">MySQL 中的事务隔离级别有哪些？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p>读未提交：脏读（读到未提交的数据）</p><p>读已提交：不可重复读（同一事务中，读取结果不同）</p><p>可重复读：幻读（数据数量变化）</p><p>串行化</p><p>MYSQL InnoDB默认：可重复读</p><h2 id="聚簇索引和非聚簇索引的区别" tabindex="-1"><a class="header-anchor" href="#聚簇索引和非聚簇索引的区别"><span>聚簇索引和非聚簇索引的区别</span></a></h2><p><a href="https://www.mianshiya.com/question/1780933295442259970" target="_blank" rel="noopener noreferrer">MySQL InnoDB 引擎中的聚簇索引和非聚簇索引有什么区别？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p><strong>聚簇索引</strong></p><p>索引叶子节点存储的是数据行，可直接访问完整数据</p><p>每个表只能有一个聚簇索引,通常是主键索引，适合范围查询和排序</p><p><strong>非聚簇索引</strong></p><p>索引叶子节点存储的是数据行的主键和对应的索引键，需通过主键才能访问完整的数据行</p><p>每个表可以有用多个非聚簇索引，适用于快速查询特定列的数据</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250318205915994.png" alt="image-20250318205915994" tabindex="0" loading="lazy"><figcaption>image-20250318205915994</figcaption></figure><h2 id="什么时候考虑使用联合索引" tabindex="-1"><a class="header-anchor" href="#什么时候考虑使用联合索引"><span>什么时候考虑使用联合索引</span></a></h2><p><strong>多列查询条件</strong>：当查询中经常涉及多个列的条件时，联合索引可以显著提高查询效率</p><p><strong>排序和分组操作</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-sql"><span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">SELECT</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> *</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> FROM</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> orders </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">ORDER BY</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> customer_id, order_date;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>范围查询和等值查询结合</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;"><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code"><code class="language-sql"><span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">SELECT</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> *</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> FROM</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> orders </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">WHERE</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> customer_id </span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">=</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 1</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> AND</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> order_date </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">BETWEEN</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">2024-01-01</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> AND</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;"> &#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">2024-12-31</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在这种情况下，联合索引 (customer_id, order_date) 可以先通过 customer_id 快速定位到相关记录，然后在这些记录中进行范围查询</p><h2 id="联合索引什么情况下会失效" tabindex="-1"><a class="header-anchor" href="#联合索引什么情况下会失效"><span>联合索引什么情况下会失效</span></a></h2><p>范围查询</p><p>查询不满足最左匹配原则</p><p><a href="https://www.mianshiya.com/question/1780933295450648578" target="_blank" rel="noopener noreferrer">MySQL 索引的最左前缀匹配原则是什么？ - 面试鸭 - 程序员求职面试刷题神器</a></p><h2 id="平时怎么进行sql优化" tabindex="-1"><a class="header-anchor" href="#平时怎么进行sql优化"><span>平时怎么进行SQL优化</span></a></h2><p><a href="https://www.mianshiya.com/question/1780933295521951745" target="_blank" rel="noopener noreferrer">MySQL 中如何进行 SQL 调优？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p>尽量避免select *，明确指定查询字段</p><p>避免全表扫描，合理设计索引，对于经常查询的字段</p><p>联表查询，使用left join左边最好使用数量量小的，子查询in适合数据量小的，因为会先进行子查询再比对外面的表，exists适合子查询数据量大的，因为会在外层循环比对里面的表</p><p>尽量避免使用函数，比如日期函数</p><p>联合索引满足，最左匹配</p><p>左like无法利用索引</p><p>or条件两侧字段未全部索引，可能导致全表扫描</p><h2 id="select-为什么比select具体字段快" tabindex="-1"><a class="header-anchor" href="#select-为什么比select具体字段快"><span>select * 为什么比select具体字段快</span></a></h2><p><a href="https://www.mianshiya.com/question/1780933295454842881" target="_blank" rel="noopener noreferrer">MySQL 的覆盖索引是什么？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p><a href="https://www.mianshiya.com/question/1780933295446454273" target="_blank" rel="noopener noreferrer">MySQL 中的回表是什么？ - 面试鸭 - 程序员求职面试刷题神器</a></p><p>减少回表次数，如果需要查询的字段只包含部分字段，可以只利用非聚簇索引就可以找到对应数据，而不用通过主键索引再获取到完整数据</p>`,119)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};